CREATE TABLE admin_account_audit (
 id TEXT PRIMARY KEY, actor_id TEXT, subject_id TEXT, action TEXT NOT NULL, occurred_at INTEGER NOT NULL
) STRICT;
CREATE TABLE admin_account_guards(id TEXT PRIMARY KEY,passed INTEGER NOT NULL CONSTRAINT admin_account_authority CHECK(passed=1)) STRICT;
CREATE TABLE admin_account_role_capabilities (
 role TEXT NOT NULL CHECK(role IN ('owner','admin','staff')), permission TEXT NOT NULL,
 PRIMARY KEY(role,permission)
) STRICT;
CREATE TABLE admin_bridge_guards(id TEXT PRIMARY KEY,passed INTEGER NOT NULL CONSTRAINT admin_bridge_state CHECK(passed=1)) STRICT;
CREATE TABLE admin_bridge_reconciliation_snapshots (
 reconciliation_id TEXT PRIMARY KEY REFERENCES reconciliations(id),
 collection_id TEXT NOT NULL REFERENCES collections(id), collection_revision INTEGER NOT NULL,
 member_id TEXT NOT NULL REFERENCES users(id), member_revision INTEGER NOT NULL,
 membership_id TEXT NOT NULL REFERENCES memberships(id), membership_revision INTEGER NOT NULL,
 payment_identity_json TEXT NOT NULL CHECK(json_valid(payment_identity_json)),
 receiver_number TEXT,receiver_network TEXT,receiver_label TEXT, created_at TEXT NOT NULL
) STRICT;
CREATE TABLE admin_bridge_requests (
 admin_user_id TEXT NOT NULL REFERENCES admin_users(id), idempotency_key TEXT NOT NULL,
 request_id TEXT NOT NULL UNIQUE, session_id TEXT NOT NULL REFERENCES auth_sessions(id), operation TEXT NOT NULL,
 body_sha256 TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(admin_user_id,idempotency_key)
) STRICT;
CREATE TABLE admin_challenges (
 token_hash TEXT PRIMARY KEY CHECK(length(token_hash)=64), user_id TEXT NOT NULL REFERENCES admin_users(id),
 kind TEXT NOT NULL CHECK(kind IN ('invite','reset')), auth_version INTEGER NOT NULL, challenge_version INTEGER NOT NULL,
 delivery_status TEXT NOT NULL DEFAULT 'pending' CHECK(delivery_status IN ('pending','accepted','failed')),
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER
) STRICT;
CREATE TABLE admin_email_events (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admin_users(id), kind TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('pending','accepted','failed')), provider_message_id TEXT,
 created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
) STRICT;
CREATE TABLE admin_grants (
 user_id TEXT NOT NULL REFERENCES users(id), permission TEXT NOT NULL,
 granted_by TEXT, granted_at TEXT NOT NULL, PRIMARY KEY(user_id,permission)
) STRICT;
CREATE TABLE admin_operator_notes (
 id TEXT PRIMARY KEY,
 entity_type TEXT NOT NULL CHECK(entity_type IN ('collection','profile')),
 entity_id TEXT NOT NULL,
 body_ciphertext TEXT NOT NULL,
 body_sha256 TEXT NOT NULL CHECK(length(body_sha256)=64),
 created_by TEXT NOT NULL REFERENCES users(id),
 session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 created_at TEXT NOT NULL
) STRICT;
CREATE TABLE admin_owner_bootstrap_claims (
 operation_id TEXT PRIMARY KEY,admin_user_id TEXT NOT NULL UNIQUE,principal_user_id TEXT NOT NULL UNIQUE,
 password_hash TEXT NOT NULL,display_name TEXT NOT NULL,approval_reference TEXT NOT NULL,
 created_at TEXT NOT NULL,created_seconds INTEGER NOT NULL
) STRICT;
CREATE TABLE admin_principal_links (
 admin_user_id TEXT PRIMARY KEY REFERENCES admin_users(id), user_id TEXT NOT NULL UNIQUE REFERENCES users(id),
 approved_by TEXT NOT NULL, approved_at TEXT NOT NULL
) STRICT;
CREATE TABLE admin_rate_limits (
 key_hash TEXT NOT NULL, bucket INTEGER NOT NULL, count INTEGER NOT NULL CHECK(count>=1), expires_at INTEGER NOT NULL,
 PRIMARY KEY(key_hash,bucket)
) STRICT;
CREATE TABLE admin_role_assignments (user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('platform_owner','operator','reviewer','auditor')),granted_by TEXT,granted_at TEXT NOT NULL,PRIMARY KEY(user_id,role)) STRICT;
CREATE TABLE admin_sessions (
 token_hash TEXT PRIMARY KEY CHECK(length(token_hash)=64), public_id TEXT NOT NULL UNIQUE,
 user_id TEXT NOT NULL REFERENCES admin_users(id), auth_version INTEGER NOT NULL,
 auth_session_id TEXT NOT NULL UNIQUE REFERENCES auth_sessions(id),
 origin TEXT NOT NULL CHECK(origin LIKE 'https://%'),
 issued_assurance_level INTEGER NOT NULL DEFAULT 1 CHECK(issued_assurance_level IN (1,2)),
 issued_mfa_at INTEGER, issued_mfa_factor_id TEXT REFERENCES auth_mfa_factors(id),
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL CHECK(expires_at>created_at),
 CHECK((issued_assurance_level=1 AND issued_mfa_at IS NULL AND issued_mfa_factor_id IS NULL)
   OR (issued_assurance_level=2 AND issued_mfa_at IS NOT NULL AND issued_mfa_factor_id IS NOT NULL))
) STRICT;
CREATE TABLE admin_users (
 id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE,
 role TEXT NOT NULL CHECK(role IN ('owner','admin','staff')),
 status TEXT NOT NULL CHECK(status IN ('invited','active','revoked')),
 display_name TEXT NOT NULL DEFAULT '', password_hash TEXT,
 auth_version INTEGER NOT NULL DEFAULT 1 CHECK(auth_version>=1),
 challenge_version INTEGER NOT NULL DEFAULT 0 CHECK(challenge_version>=0),
 created_at INTEGER NOT NULL, invited_at INTEGER, accepted_at INTEGER, updated_at INTEGER NOT NULL,
 CHECK((role='owner' AND email='info@ikanisa.com') OR (role!='owner' AND email!='info@ikanisa.com')),
 CHECK(status!='active' OR password_hash IS NOT NULL)
) STRICT;
CREATE TABLE audit_log (
 id INTEGER PRIMARY KEY AUTOINCREMENT, actor_user_id TEXT REFERENCES users(id), actor_session_id TEXT,
 action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, request_id TEXT,
 details_json TEXT NOT NULL CHECK(json_valid(details_json)), created_at TEXT NOT NULL
) STRICT;
CREATE TABLE auth_mfa_budgets (
 user_id TEXT NOT NULL REFERENCES users(id), window_start INTEGER NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('challenge','verification')), used INTEGER NOT NULL CHECK(used>=1 AND used<=10),
 PRIMARY KEY(user_id,window_start,kind)
);
CREATE TABLE auth_mfa_challenges (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 factor_id TEXT NOT NULL REFERENCES auth_mfa_factors(id), created_at INTEGER NOT NULL,
 expires_at INTEGER NOT NULL CHECK(expires_at>created_at), attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),
 consumed_at INTEGER, consumed_operation_id TEXT UNIQUE,
 CHECK((consumed_at IS NULL AND consumed_operation_id IS NULL) OR (consumed_at IS NOT NULL AND consumed_operation_id IS NOT NULL))
);
CREATE TABLE auth_mfa_claims (
 operation_id TEXT PRIMARY KEY, challenge_id TEXT NOT NULL UNIQUE REFERENCES auth_mfa_challenges(id),
 factor_id TEXT NOT NULL REFERENCES auth_mfa_factors(id), user_id TEXT NOT NULL REFERENCES users(id),
 session_id TEXT NOT NULL REFERENCES auth_sessions(id), totp_counter INTEGER NOT NULL CHECK(totp_counter>=0),
 verified_at INTEGER NOT NULL, UNIQUE(factor_id,totp_counter)
);
CREATE TABLE auth_mfa_factors (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), friendly_name TEXT NOT NULL,
 secret_ciphertext TEXT NOT NULL CHECK(json_valid(secret_ciphertext)),
 status TEXT NOT NULL CHECK(status IN ('pending','verified','revoked')),
 created_at INTEGER NOT NULL, enrollment_session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 verified_at INTEGER, last_totp_counter INTEGER CHECK(last_totp_counter>=0), revoked_at INTEGER,
 CHECK((status='pending' AND verified_at IS NULL AND last_totp_counter IS NULL AND revoked_at IS NULL)
    OR (status='verified' AND verified_at IS NOT NULL AND last_totp_counter IS NOT NULL AND revoked_at IS NULL)
    OR (status='revoked' AND revoked_at IS NOT NULL))
);
CREATE TABLE auth_mfa_revocations (
 operation_id TEXT PRIMARY KEY, factor_id TEXT NOT NULL UNIQUE REFERENCES auth_mfa_factors(id),
 user_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES auth_sessions(id), revoked_at INTEGER NOT NULL
);
CREATE TABLE auth_otp_challenges (
 id TEXT PRIMARY KEY,
 identity_hash TEXT NOT NULL CHECK(length(identity_hash)=64),
 identity_type TEXT NOT NULL CHECK(identity_type IN ('phone','email')),
 identity_value TEXT NOT NULL,
 surface TEXT NOT NULL CHECK(surface IN ('member','admin')),
 registration_allowed INTEGER NOT NULL CHECK(registration_allowed IN (0,1)),
 code_hash TEXT NOT NULL CHECK(length(code_hash)=64),
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL CHECK(expires_at>created_at),
 attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),
 status TEXT NOT NULL CHECK(status IN ('dispatching','accepted','delivery_unknown','superseded','consumed')),
 consumed_at INTEGER, consumed_operation_id TEXT UNIQUE,
 CHECK((status='consumed' AND consumed_at IS NOT NULL AND consumed_operation_id IS NOT NULL)
    OR (status!='consumed' AND consumed_at IS NULL AND consumed_operation_id IS NULL))
);
CREATE TABLE auth_otp_throttles (
 identity_hash TEXT PRIMARY KEY, last_requested_at INTEGER NOT NULL
);
CREATE TABLE auth_otp_verifications (
 operation_id TEXT PRIMARY KEY, challenge_id TEXT NOT NULL UNIQUE REFERENCES auth_otp_challenges(id),
 user_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL UNIQUE REFERENCES auth_sessions(id),
 verified_at INTEGER NOT NULL
);
CREATE TABLE auth_rate_buckets (
 bucket_key TEXT PRIMARY KEY, used INTEGER NOT NULL CHECK(used>=0),
 window_ends_at INTEGER NOT NULL
);
CREATE TABLE auth_rate_claims (
 request_id TEXT PRIMARY KEY,
 identity_hash TEXT NOT NULL, identity_bucket TEXT NOT NULL,
 ip_bucket TEXT NOT NULL, global_bucket TEXT NOT NULL,
 requested_at INTEGER NOT NULL, hourly_window_ends_at INTEGER NOT NULL,
 daily_window_ends_at INTEGER NOT NULL,
 identity_limit INTEGER NOT NULL CHECK(identity_limit BETWEEN 1 AND 100),
 ip_limit INTEGER NOT NULL CHECK(ip_limit BETWEEN 1 AND 1000),
 global_limit INTEGER NOT NULL CHECK(global_limit BETWEEN 1 AND 100000),
 cooldown_seconds INTEGER NOT NULL CHECK(cooldown_seconds BETWEEN 60 AND 3600)
);
CREATE TABLE auth_refresh_tokens (
 token_hash TEXT PRIMARY KEY CHECK(length(token_hash)=64),
 session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL CHECK(expires_at>created_at),
 used_at INTEGER, replaced_by_hash TEXT,
 CHECK((used_at IS NULL AND replaced_by_hash IS NULL)
    OR (used_at IS NOT NULL AND length(replaced_by_hash)=64))
);
CREATE TABLE auth_sessions (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id),
 surface TEXT NOT NULL CHECK(surface IN ('member','admin')),
 auth_at INTEGER NOT NULL, created_at INTEGER NOT NULL,
 expires_at INTEGER NOT NULL CHECK(expires_at>created_at),
 revoked_at INTEGER, revocation_reason TEXT,
 assurance_level INTEGER NOT NULL DEFAULT 1 CHECK(assurance_level IN (1,2)),
 mfa_at INTEGER, mfa_factor_id TEXT REFERENCES auth_mfa_factors(id),
 CHECK((assurance_level=1 AND mfa_at IS NULL AND mfa_factor_id IS NULL)
    OR (assurance_level=2 AND mfa_at>=auth_at AND mfa_factor_id IS NOT NULL)),
 CHECK((revoked_at IS NULL AND revocation_reason IS NULL)
    OR (revoked_at IS NOT NULL AND revocation_reason IS NOT NULL))
);
CREATE TABLE collections (
 id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, creator_user_id TEXT NOT NULL REFERENCES users(id),
 title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', collection_type TEXT NOT NULL,
 country_code TEXT NOT NULL DEFAULT 'RW' CHECK(country_code='RW'), currency TEXT NOT NULL DEFAULT 'RWF' CHECK(currency='RWF'),
 status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived','suspended')),
 visibility_status TEXT NOT NULL DEFAULT 'private' CHECK(visibility_status IN ('private','public_pending','public_approved')),
 is_platform_sponsored INTEGER NOT NULL DEFAULT 0 CHECK(is_platform_sponsored IN (0,1)),
 receiver_momo_number TEXT, receiver_network TEXT, receiver_display_label TEXT,
 share_code_hash TEXT UNIQUE, share_code_ciphertext TEXT, share_code_version INTEGER NOT NULL DEFAULT 1,
 revision INTEGER NOT NULL DEFAULT 1, data_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data_json)),
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
) STRICT;
CREATE TABLE deletion_requests (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), submission_id TEXT NOT NULL,
 reason TEXT, status TEXT NOT NULL DEFAULT 'received' CHECK(status IN ('received','under_review','scheduled','erasing','completed','rejected','on_hold','failed')),
 revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 UNIQUE(user_id,submission_id)
) STRICT;
CREATE TABLE deletion_reviews (
 id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES deletion_requests(id), actor_user_id TEXT NOT NULL REFERENCES users(id),
 expected_revision INTEGER NOT NULL, outcome TEXT NOT NULL, details_json TEXT NOT NULL CHECK(json_valid(details_json)),
 created_at TEXT NOT NULL
) STRICT;
CREATE TABLE ledger_entries (
 id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments(id), collection_id TEXT NOT NULL REFERENCES collections(id),
 member_id TEXT REFERENCES users(id), currency TEXT NOT NULL DEFAULT 'RWF' CHECK(currency='RWF'),
 amount_minor INTEGER NOT NULL CHECK(amount_minor!=0 AND abs(amount_minor)<=9007199254740991),
 kind TEXT NOT NULL CHECK(kind IN ('contribution','reversal','correction')),
 reverses_entry_id TEXT UNIQUE REFERENCES ledger_entries(id), evidence_id TEXT NOT NULL REFERENCES payment_evidence(id),
 actor_user_id TEXT NOT NULL REFERENCES users(id), request_id TEXT NOT NULL UNIQUE, posted_at TEXT NOT NULL,
 CHECK((kind='contribution' AND amount_minor>0 AND reverses_entry_id IS NULL) OR (kind!='contribution' AND reverses_entry_id IS NOT NULL))
) STRICT;
CREATE TABLE memberships (
 id TEXT PRIMARY KEY, collection_id TEXT NOT NULL REFERENCES collections(id), user_id TEXT NOT NULL REFERENCES users(id),
 role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('owner','admin','member')),
 active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), joined_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>=1),
 UNIQUE(collection_id,user_id)
) STRICT;
CREATE TABLE mutation_guards (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL, session_id TEXT NOT NULL, now_seconds INTEGER NOT NULL,
 collection_id TEXT, required_group_role TEXT, permission TEXT, fresh_seconds INTEGER,
 expected_collection_revision INTEGER, payment_id TEXT, expected_payment_revision INTEGER,
 minimum_assurance INTEGER, expected_mfa_at INTEGER, expected_preference_revision INTEGER, invite_collection_id TEXT,expected_share_hash TEXT,expected_share_version INTEGER,recipient_user_id TEXT,recipient_collection_id TEXT
, target_collection_id TEXT, expected_target_collection_revision INTEGER);
CREATE TABLE native_capabilities (
 id TEXT PRIMARY KEY, token_sha256 TEXT NOT NULL UNIQUE CHECK(length(token_sha256)=64), reservation_id TEXT NOT NULL UNIQUE REFERENCES native_reservations(id),
 user_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES auth_sessions(id), action TEXT NOT NULL,
 receiver_hash TEXT NOT NULL, verified_phone TEXT NOT NULL, payload_sha256 TEXT NOT NULL,
 created_seconds INTEGER NOT NULL, expires_seconds INTEGER NOT NULL CHECK(expires_seconds>created_seconds AND expires_seconds<=created_seconds+180),
 verdict_sha256 TEXT NOT NULL CHECK(length(verdict_sha256)=64)
);
CREATE TABLE native_capability_claims (
 id TEXT PRIMARY KEY, capability_id TEXT NOT NULL UNIQUE REFERENCES native_capabilities(id), user_id TEXT NOT NULL, session_id TEXT NOT NULL,
 action TEXT NOT NULL, payload_sha256 TEXT NOT NULL, receiver_hash TEXT NOT NULL, claimed_seconds INTEGER NOT NULL
);
CREATE TABLE native_completions (
 reservation_id TEXT PRIMARY KEY REFERENCES native_reservations(id), capability_id TEXT NOT NULL UNIQUE REFERENCES native_capabilities(id),
 result_ciphertext TEXT NOT NULL, provider_response_sha256 TEXT NOT NULL, completed_seconds INTEGER NOT NULL,
 decode_duration_ms INTEGER NOT NULL CHECK(decode_duration_ms BETWEEN 0 AND 20000)
);
CREATE TABLE native_consents (
 id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 receiver_hash TEXT NOT NULL CHECK(length(receiver_hash)=64), enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),
 created_seconds INTEGER NOT NULL, build_channel TEXT NOT NULL, request_id TEXT NOT NULL UNIQUE
);
CREATE TABLE native_phases (
 reservation_id TEXT NOT NULL REFERENCES native_reservations(id), phase TEXT NOT NULL CHECK(phase IN('oauth','decode')),
 started_seconds INTEGER NOT NULL, PRIMARY KEY(reservation_id,phase)
);
CREATE TABLE native_reservations (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 nonce TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN('group.create','sms.ingest')),
 request_hash TEXT NOT NULL CHECK(length(request_hash)=64), token_sha256 TEXT NOT NULL UNIQUE CHECK(length(token_sha256)=64),
 receiver_hash TEXT NOT NULL CHECK(length(receiver_hash)=64), verified_phone TEXT NOT NULL,
 payload_sha256 TEXT NOT NULL CHECK(length(payload_sha256)=64), payload_ciphertext TEXT NOT NULL,
 policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64), approval_id TEXT NOT NULL, approval_evidence_sha256 TEXT NOT NULL,
 project_id TEXT NOT NULL, created_seconds INTEGER NOT NULL, expires_seconds INTEGER NOT NULL,
 actor_hour_limit INTEGER NOT NULL CHECK(actor_hour_limit BETWEEN 1 AND 100), project_day_limit INTEGER NOT NULL CHECK(project_day_limit BETWEEN 1 AND 10000),
 state TEXT NOT NULL DEFAULT 'reserved' CHECK(state IN('reserved','oauth_started','decode_started','completed','rejected','ambiguous')),
 UNIQUE(user_id,nonce)
);
CREATE TABLE notification_devices (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL UNIQUE,
 owner_session_id TEXT NOT NULL, provider TEXT NOT NULL, token_ciphertext TEXT NOT NULL, platform TEXT NOT NULL CHECK(platform IN ('android','ios','web')),
 active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
) STRICT;
CREATE TABLE notification_events (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), event_type TEXT NOT NULL, title TEXT NOT NULL,
 body TEXT NOT NULL, data_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data_json)),
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','failed','read')),
 created_at TEXT NOT NULL, read_at TEXT
) STRICT;
CREATE TABLE notification_preferences (
 user_id TEXT PRIMARY KEY REFERENCES users(id), push_enabled INTEGER NOT NULL DEFAULT 1, payment_updates INTEGER NOT NULL DEFAULT 1,
 group_updates INTEGER NOT NULL DEFAULT 1, revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL
) STRICT;
CREATE TABLE payment_evidence (
 id TEXT PRIMARY KEY, collection_id TEXT REFERENCES collections(id), owner_user_id TEXT NOT NULL REFERENCES users(id),
 object_key TEXT NOT NULL UNIQUE, object_sha256 TEXT NOT NULL CHECK(length(object_sha256)=64),
 size_bytes INTEGER NOT NULL CHECK(size_bytes>0), content_type TEXT NOT NULL,
 authenticity TEXT NOT NULL CHECK(authenticity IN ('operator_recorded','provider_authenticated')),
 external_reference TEXT, receiver_momo_number TEXT, amount_minor INTEGER CHECK(amount_minor IS NULL OR (amount_minor>0 AND amount_minor<=9007199254740991)),
 currency TEXT NOT NULL DEFAULT 'RWF' CHECK(currency='RWF'), observed_at TEXT NOT NULL, created_at TEXT NOT NULL,
 retained_until TEXT, legal_hold INTEGER NOT NULL DEFAULT 0 CHECK(legal_hold IN (0,1)), receiver_network TEXT, receiver_display_label TEXT,
 UNIQUE(owner_user_id,external_reference)
) STRICT;
CREATE TABLE payment_intents (
 id TEXT PRIMARY KEY, collection_id TEXT NOT NULL REFERENCES collections(id), member_id TEXT NOT NULL REFERENCES users(id),
 amount_minor INTEGER NOT NULL CHECK(amount_minor>0 AND amount_minor<=9007199254740991),
 currency TEXT NOT NULL DEFAULT 'RWF' CHECK(currency='RWF'), rail TEXT NOT NULL DEFAULT 'rwanda_momo' CHECK(rail='rwanda_momo'),
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','expired','cancelled','matched','ambiguous')),
 receiver_momo_number TEXT NOT NULL, receiver_network TEXT NOT NULL, receiver_label TEXT NOT NULL DEFAULT '',
 originating_session_id TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL,
 request_id TEXT NOT NULL, request_sha256 TEXT NOT NULL, UNIQUE(member_id,request_id)
) STRICT;
CREATE TABLE payments (
 id TEXT PRIMARY KEY, collection_id TEXT NOT NULL REFERENCES collections(id), member_id TEXT REFERENCES users(id),
 evidence_id TEXT NOT NULL REFERENCES payment_evidence(id), intent_id TEXT REFERENCES payment_intents(id),
 amount_minor INTEGER NOT NULL CHECK(amount_minor>0 AND amount_minor<=9007199254740991),
 currency TEXT NOT NULL DEFAULT 'RWF' CHECK(currency='RWF'), rail TEXT NOT NULL DEFAULT 'rwanda_momo' CHECK(rail='rwanda_momo'),
 status TEXT NOT NULL CHECK(status IN ('recorded','reconciled','confirmed','corrected','reversed','ambiguous')),
 payer_display_name TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
 UNIQUE(evidence_id)
) STRICT;
CREATE TABLE privacy_holds (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), category TEXT NOT NULL, reason_code TEXT NOT NULL,
 active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, released_at TEXT
) STRICT;
CREATE TABLE privacy_retention_barriers (
 subject_id TEXT PRIMARY KEY REFERENCES users(id), plan_id TEXT NOT NULL UNIQUE REFERENCES privacy_retention_plans(id),
 source_id TEXT NOT NULL CHECK(length(source_id)=64), policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64),
 activated_seconds INTEGER NOT NULL
) STRICT;
CREATE TABLE privacy_retention_claims (
 id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, task_id TEXT NOT NULL REFERENCES privacy_retention_tasks(id),
 actor_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64), expected_revision INTEGER NOT NULL,
 fence INTEGER NOT NULL CHECK(fence>0), claimed_seconds INTEGER NOT NULL, expires_seconds INTEGER NOT NULL,
 CHECK(expires_seconds>claimed_seconds AND expires_seconds<=claimed_seconds+120)
) STRICT;
CREATE TABLE privacy_retention_effects (
 operation_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES privacy_retention_tasks(id),
 claim_id TEXT NOT NULL REFERENCES privacy_retention_claims(id), fence INTEGER NOT NULL,
 source_sha256 TEXT NOT NULL CHECK(length(source_sha256)=64),
 object_key TEXT NOT NULL, object_version TEXT NOT NULL, started_seconds INTEGER NOT NULL,
 UNIQUE(task_id,object_key)
) STRICT;
CREATE TABLE privacy_retention_guards (
 id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES privacy_retention_plans(id), class_name TEXT NOT NULL,
 passed INTEGER NOT NULL CHECK(passed=1)
) STRICT;
CREATE TABLE privacy_retention_outcomes (
 operation_id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES privacy_retention_tasks(id), claim_id TEXT NOT NULL REFERENCES privacy_retention_claims(id),
 fence INTEGER NOT NULL, input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64),
 outcome_json TEXT NOT NULL CHECK(json_valid(outcome_json)), observed_seconds INTEGER NOT NULL
) STRICT;
CREATE TABLE privacy_retention_plans (
 id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, request_id TEXT NOT NULL REFERENCES deletion_requests(id),
 subject_id TEXT NOT NULL REFERENCES users(id), actor_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64), policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64),
 policy_json TEXT NOT NULL CHECK(json_valid(policy_json)), policy_config_revision INTEGER NOT NULL,
 source_id TEXT NOT NULL CHECK(length(source_id)=64), schema_sha256 TEXT NOT NULL CHECK(length(schema_sha256)=64),
 scope_json TEXT NOT NULL CHECK(json_valid(scope_json)), scope_sha256 TEXT NOT NULL CHECK(length(scope_sha256)=64),
 ledger_sha256 TEXT NOT NULL CHECK(length(ledger_sha256)=64), review_revision INTEGER NOT NULL,
 state TEXT NOT NULL DEFAULT 'planned' CHECK(state IN('planned','processing','blocked','disposition_verified')),
 revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0), created_seconds INTEGER NOT NULL
) STRICT;
CREATE TABLE privacy_retention_tasks (
 id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES privacy_retention_plans(id), class_name TEXT NOT NULL,
 action TEXT NOT NULL CHECK(action IN('retain','erase','quarantine','blocked')),
 expected_json TEXT NOT NULL CHECK(json_valid(expected_json)), state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','claimed','blocked','verified')),
 revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0), fence INTEGER NOT NULL DEFAULT 0 CHECK(fence>=0),
 claim_id TEXT, post_images_json TEXT CHECK(post_images_json IS NULL OR json_valid(post_images_json)),
 outcome_json TEXT CHECK(outcome_json IS NULL OR json_valid(outcome_json)), UNIQUE(plan_id,class_name)
) STRICT;
CREATE TABLE privacy_review_claims (
 claim_id TEXT PRIMARY KEY, claim_request_id TEXT NOT NULL UNIQUE, request_id TEXT NOT NULL REFERENCES deletion_requests(id),
 actor_id TEXT NOT NULL REFERENCES users(id), originating_session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 expected_revision INTEGER NOT NULL CHECK(expected_revision BETWEEN 0 AND 999999998),
 revision INTEGER NOT NULL CHECK(revision=expected_revision+1), fence INTEGER NOT NULL CHECK(fence BETWEEN 1 AND 1000000000),
 lease_seconds INTEGER NOT NULL CHECK(lease_seconds BETWEEN 1 AND 120), claimed_at TEXT NOT NULL, expires_at TEXT NOT NULL CHECK(expires_at>claimed_at)
);
CREATE TABLE privacy_review_heads (
 request_id TEXT PRIMARY KEY REFERENCES deletion_requests(id),
 revision INTEGER NOT NULL DEFAULT 0 CHECK(revision BETWEEN 0 AND 1000000000),
 fence INTEGER NOT NULL DEFAULT 0 CHECK(fence BETWEEN 0 AND 1000000000),
 state TEXT NOT NULL DEFAULT 'awaiting_review' CHECK(state IN ('awaiting_review','claim_active','blocked')),
 latest_claim_id TEXT REFERENCES privacy_review_claims(claim_id), last_outcome_id TEXT REFERENCES privacy_review_outcomes(outcome_request_id),
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 CHECK((state='awaiting_review' AND revision=0 AND fence=0 AND latest_claim_id IS NULL AND last_outcome_id IS NULL)
 OR (state='claim_active' AND revision>0 AND fence>0 AND latest_claim_id IS NOT NULL AND last_outcome_id IS NULL)
 OR (state='blocked' AND revision>=2 AND fence>0 AND latest_claim_id IS NOT NULL AND last_outcome_id IS NOT NULL))
);
CREATE TABLE privacy_review_outcomes (
 outcome_request_id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES deletion_requests(id),
 claim_id TEXT NOT NULL UNIQUE REFERENCES privacy_review_claims(claim_id), actor_id TEXT NOT NULL REFERENCES users(id),
 originating_session_id TEXT NOT NULL REFERENCES auth_sessions(id), fence INTEGER NOT NULL CHECK(fence>0),
 revision INTEGER NOT NULL CHECK(revision BETWEEN 2 AND 1000000000),
 outcome_code TEXT NOT NULL CHECK(outcome_code='policy_authority_unavailable'), recorded_at TEXT NOT NULL
);
CREATE TABLE privacy_submissions (
 submission_id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES deletion_requests(id),
 user_id TEXT NOT NULL REFERENCES users(id), originating_session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64), created_at TEXT NOT NULL
);
CREATE TABLE reconciliations (
 id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments(id), proposed_member_id TEXT NOT NULL REFERENCES users(id),
 proposed_by TEXT NOT NULL REFERENCES users(id), proposed_session_id TEXT NOT NULL,
 expected_payment_revision INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('proposed','approved','rejected','cancelled')),
 evidence_id TEXT NOT NULL REFERENCES payment_evidence(id), approved_by TEXT REFERENCES users(id),
 request_id TEXT NOT NULL UNIQUE, request_sha256 TEXT NOT NULL, created_at TEXT NOT NULL, approved_at TEXT
) STRICT;
CREATE TABLE request_receipts (
 user_id TEXT NOT NULL REFERENCES users(id), request_id TEXT NOT NULL, operation TEXT NOT NULL,
 session_id TEXT NOT NULL, body_sha256 TEXT NOT NULL CHECK(length(body_sha256)=64), response_json TEXT NOT NULL CHECK(json_valid(response_json)),
 created_at TEXT NOT NULL, PRIMARY KEY(user_id,request_id)
) STRICT;
CREATE TABLE roster_commit_guards (
 id TEXT PRIMARY KEY, import_id TEXT NOT NULL, revision_id TEXT, actor_user_id TEXT NOT NULL, session_id TEXT NOT NULL,
 now_seconds INTEGER NOT NULL, expected_state TEXT NOT NULL, expected_latest_revision TEXT, permission TEXT NOT NULL DEFAULT 'roster.import',
 collection_id TEXT, expected_collection_revision INTEGER
);
CREATE TABLE roster_dispatch_phases (
 processing_id TEXT NOT NULL REFERENCES roster_processing_records(id), phase TEXT NOT NULL CHECK(phase IN('decode','extract')),
 started_seconds INTEGER NOT NULL, PRIMARY KEY(processing_id,phase)
);
CREATE TABLE roster_imports (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES auth_sessions(id), request_id TEXT NOT NULL,
 collection_id TEXT REFERENCES collections(id), request_sha256 TEXT NOT NULL, source_sha256 TEXT NOT NULL, object_sha256 TEXT NOT NULL,
 source_object_key TEXT NOT NULL UNIQUE, source_size INTEGER NOT NULL CHECK(source_size BETWEEN 1 AND 5242880),
 source_kind TEXT NOT NULL, source_receipt_json TEXT NOT NULL CHECK(json_valid(source_receipt_json)),
 state TEXT NOT NULL CHECK(state IN('reserved','retained','processing','preview_ready','committed','failed','ambiguous')), latest_revision_id TEXT,
 source_ciphertext TEXT NOT NULL,
 created_seconds INTEGER NOT NULL, expires_seconds INTEGER NOT NULL, error_code TEXT, UNIQUE(user_id,request_id)
);
CREATE TABLE roster_intents (
 id TEXT PRIMARY KEY, import_id TEXT NOT NULL REFERENCES roster_imports(id), user_id TEXT NOT NULL, session_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN('review','commit')), request_id TEXT NOT NULL, body_sha256 TEXT NOT NULL,
 payload_ciphertext TEXT NOT NULL, created_seconds INTEGER NOT NULL, UNIQUE(import_id,request_id)
);
CREATE TABLE roster_members (
 id TEXT PRIMARY KEY, collection_id TEXT NOT NULL REFERENCES collections(id), source_import_id TEXT NOT NULL REFERENCES roster_imports(id),
 source_revision_id TEXT NOT NULL REFERENCES roster_revisions(id), member_name TEXT NOT NULL, momo_name TEXT NOT NULL,
 momo_number TEXT NOT NULL, linked_user_id TEXT REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(collection_id,momo_number)
);
CREATE TABLE roster_processing_records (
 id TEXT PRIMARY KEY, import_id TEXT NOT NULL UNIQUE REFERENCES roster_imports(id), actor_user_id TEXT NOT NULL, session_id TEXT NOT NULL,
 source_sha256 TEXT NOT NULL, source_object_sha256 TEXT NOT NULL, policy_sha256 TEXT NOT NULL, approval_id TEXT NOT NULL,
 approval_evidence_sha256 TEXT NOT NULL, processor_policy_json TEXT NOT NULL CHECK(json_valid(processor_policy_json)),
 project_id TEXT NOT NULL, organization_id TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL,
 processing_region_evidence_ref TEXT NOT NULL, retention_evidence_ref TEXT NOT NULL, decoder_build_sha256 TEXT NOT NULL,
 decoder_lineage_json TEXT NOT NULL CHECK(json_valid(decoder_lineage_json)), created_seconds INTEGER NOT NULL, expires_seconds INTEGER NOT NULL
);
CREATE TABLE roster_revisions (
 id TEXT PRIMARY KEY, import_id TEXT NOT NULL REFERENCES roster_imports(id), request_id TEXT NOT NULL, parent_revision_id TEXT REFERENCES roster_revisions(id),
 revision_number INTEGER NOT NULL CHECK(revision_number BETWEEN 1 AND 20), rows_sha256 TEXT NOT NULL, preview_ciphertext TEXT NOT NULL,
 human_reviewed INTEGER NOT NULL CHECK(human_reviewed IN(0,1)), review_reason TEXT, created_seconds INTEGER NOT NULL, UNIQUE(import_id,request_id),UNIQUE(import_id,revision_number)
);
CREATE TABLE runtime_config (
 key TEXT PRIMARY KEY, value_json TEXT NOT NULL CHECK(json_valid(value_json)), revision INTEGER NOT NULL DEFAULT 1,
 updated_by TEXT REFERENCES users(id), updated_at TEXT NOT NULL
) STRICT;
CREATE TABLE sms_receipts (
 id TEXT PRIMARY KEY NOT NULL,owner_user_id TEXT NOT NULL REFERENCES users(id),originating_session_id TEXT NOT NULL REFERENCES auth_sessions(id),
 client_envelope_id TEXT NOT NULL,body_sha256 TEXT NOT NULL CHECK(length(body_sha256)=64),
 receiver_hash TEXT NOT NULL CHECK(length(receiver_hash)=64),object_key TEXT NOT NULL UNIQUE,object_sha256 TEXT NOT NULL CHECK(length(object_sha256)=64),
 size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 1 AND 131072),received_at_device TEXT,
 status TEXT NOT NULL DEFAULT 'received' CHECK(status IN('received','under_review','rejected','linked')),
 evidence_level TEXT NOT NULL DEFAULT 'client_received' CHECK(evidence_level='client_received'),created_at TEXT NOT NULL,
 UNIQUE(owner_user_id,client_envelope_id)
) STRICT;
CREATE TABLE support_requests (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), collection_id TEXT REFERENCES collections(id),
 kind TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'received', created_at TEXT NOT NULL
) STRICT;
CREATE TABLE upload_objects (
 id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), collection_id TEXT REFERENCES collections(id),
 object_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, size_bytes INTEGER NOT NULL, content_type TEXT NOT NULL,
 purpose TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'retained', created_at TEXT NOT NULL, deleted_at TEXT
) STRICT;
CREATE TABLE users (
 id TEXT PRIMARY KEY, phone TEXT UNIQUE, email TEXT UNIQUE, full_name TEXT NOT NULL DEFAULT '',
 public_id TEXT NOT NULL UNIQUE, country_code TEXT NOT NULL DEFAULT 'RW',
 currency_code TEXT NOT NULL DEFAULT 'RWF', momo_provider TEXT NOT NULL DEFAULT '',
 momo_number TEXT NOT NULL DEFAULT '', momo_pay_code TEXT NOT NULL DEFAULT '',
 access_status TEXT NOT NULL DEFAULT 'active' CHECK(access_status IN ('active','suspended','deleted')),
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
, member_type TEXT NOT NULL DEFAULT 'app' CHECK(member_type IN ('app','direct','operator')), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>=1)) STRICT;
PRAGMA defer_foreign_keys=TRUE;
