CREATE TRIGGER admin_account_audit_no_delete BEFORE DELETE ON admin_account_audit
 BEGIN SELECT RAISE(ABORT,'retain_admin_account_audit'); END;
CREATE TRIGGER admin_account_audit_no_update BEFORE UPDATE ON admin_account_audit
 BEGIN SELECT RAISE(ABORT,'immutable_admin_account_audit'); END;
CREATE TRIGGER admin_account_authority_changed AFTER UPDATE OF status,role,auth_version ON admin_users
 WHEN NEW.status!=OLD.status OR NEW.role!=OLD.role OR NEW.auth_version!=OLD.auth_version BEGIN
 UPDATE auth_sessions SET revoked_at=unixepoch(),revocation_reason='admin_account_changed'
 WHERE user_id=(SELECT user_id FROM admin_principal_links WHERE admin_user_id=NEW.id) AND surface='admin' AND revoked_at IS NULL;
 DELETE FROM admin_sessions WHERE user_id=NEW.id;
 DELETE FROM admin_grants WHERE user_id=(SELECT user_id FROM admin_principal_links WHERE admin_user_id=NEW.id) AND granted_by='admin-account:'||NEW.id;
 DELETE FROM admin_role_assignments WHERE user_id=(SELECT user_id FROM admin_principal_links WHERE admin_user_id=NEW.id) AND granted_by='admin-account:'||NEW.id;
 INSERT OR IGNORE INTO admin_grants(user_id,permission,granted_by,granted_at)
 SELECT l.user_id,c.permission,'admin-account:'||NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')
 FROM admin_principal_links l JOIN admin_account_role_capabilities c ON c.role=NEW.role WHERE l.admin_user_id=NEW.id AND NEW.status='active';
 INSERT OR IGNORE INTO admin_role_assignments(user_id,role,granted_by,granted_at)
 SELECT l.user_id,(CASE WHEN NEW.role='owner' THEN 'platform_owner' ELSE 'operator' END),'admin-account:'||NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')
 FROM admin_principal_links l WHERE l.admin_user_id=NEW.id AND NEW.status='active';
END;
CREATE TRIGGER admin_bridge_reconciliation_snapshot_no_delete BEFORE DELETE ON admin_bridge_reconciliation_snapshots
 BEGIN SELECT RAISE(ABORT,'retain_reconciliation_snapshot'); END;
CREATE TRIGGER admin_bridge_reconciliation_snapshot_no_update BEFORE UPDATE ON admin_bridge_reconciliation_snapshots
 BEGIN SELECT RAISE(ABORT,'immutable_reconciliation_snapshot'); END;
CREATE TRIGGER admin_bridge_request_no_delete BEFORE DELETE ON admin_bridge_requests BEGIN SELECT RAISE(ABORT,'retain_admin_bridge_request'); END;
CREATE TRIGGER admin_bridge_request_no_update BEFORE UPDATE ON admin_bridge_requests BEGIN SELECT RAISE(ABORT,'immutable_admin_bridge_request'); END;
CREATE TRIGGER admin_cookie_mfa_bound BEFORE UPDATE OF issued_assurance_level,issued_mfa_at,issued_mfa_factor_id ON admin_sessions
 WHEN NEW.issued_assurance_level=2 BEGIN
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM auth_sessions s JOIN auth_mfa_factors f ON f.id=s.mfa_factor_id
 WHERE s.id=NEW.auth_session_id AND s.assurance_level=2 AND s.mfa_at=NEW.issued_mfa_at AND s.mfa_factor_id=NEW.issued_mfa_factor_id
 AND s.revoked_at IS NULL AND s.expires_at>unixepoch() AND f.status='verified') THEN RAISE(ABORT,'real_mfa_required') END);
END;
CREATE TRIGGER admin_cookie_session_bound BEFORE INSERT ON admin_sessions BEGIN
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM admin_users a JOIN admin_principal_links l ON l.admin_user_id=a.id
 JOIN users u ON u.id=l.user_id JOIN auth_sessions s ON s.user_id=u.id
 WHERE a.id=NEW.user_id AND a.status='active' AND a.auth_version=NEW.auth_version AND u.access_status='active'
 AND s.id=NEW.auth_session_id AND s.surface='admin' AND s.auth_at=NEW.created_at AND s.revoked_at IS NULL
 AND s.expires_at=NEW.expires_at AND NEW.issued_assurance_level=1)
 THEN RAISE(ABORT,'admin_session_link_required') END);
END;
CREATE TRIGGER admin_cookie_session_revoked AFTER DELETE ON admin_sessions BEGIN
 UPDATE auth_sessions SET revoked_at=unixepoch(),revocation_reason='admin_cookie_session_ended' WHERE id=OLD.auth_session_id AND revoked_at IS NULL;
END;
CREATE TRIGGER admin_link_grants AFTER INSERT ON admin_principal_links BEGIN
 INSERT OR IGNORE INTO admin_grants(user_id,permission,granted_by,granted_at)
 SELECT NEW.user_id,c.permission,'admin-account:'||u.id,strftime('%Y-%m-%dT%H:%M:%fZ','now')
 FROM admin_users u JOIN admin_account_role_capabilities c ON c.role=u.role WHERE u.id=NEW.admin_user_id AND u.status='active';
 INSERT OR IGNORE INTO admin_role_assignments(user_id,role,granted_by,granted_at)
 SELECT NEW.user_id,(CASE WHEN u.role='owner' THEN 'platform_owner' ELSE 'operator' END),
 'admin-account:'||u.id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM admin_users u WHERE u.id=NEW.admin_user_id AND u.status='active';
END;
CREATE TRIGGER admin_operator_note_target BEFORE INSERT ON admin_operator_notes BEGIN
 SELECT (CASE WHEN (NEW.entity_type='collection' AND NOT EXISTS(SELECT 1 FROM collections WHERE id=NEW.entity_id))
 OR (NEW.entity_type='profile' AND NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.entity_id))
 THEN RAISE(ABORT,'operator_note_target_unavailable') END);
END;
CREATE TRIGGER admin_owner_bootstrap_admission BEFORE INSERT ON admin_owner_bootstrap_claims BEGIN
 SELECT (CASE WHEN EXISTS(SELECT 1 FROM admin_users WHERE role='owner') OR length(NEW.approval_reference)<8
  OR NEW.password_hash NOT GLOB 'pbkdf2-sha256$600000$*' OR EXISTS(SELECT 1 FROM users WHERE id=NEW.principal_user_id)
  THEN RAISE(ABORT,'explicit_fresh_owner_bootstrap_required') END);
END;
CREATE TRIGGER admin_owner_bootstrap_apply AFTER INSERT ON admin_owner_bootstrap_claims BEGIN
 INSERT INTO users(id,public_id,full_name,member_type,created_at,updated_at)
 VALUES(NEW.principal_user_id,(SELECT printf('%06d',min(candidate)) FROM
 (SELECT 0 AS candidate UNION ALL SELECT CAST(public_id AS INTEGER)+1 FROM users WHERE public_id!='999999') c
 WHERE candidate<1000000 AND NOT EXISTS(SELECT 1 FROM users WHERE public_id=printf('%06d',candidate))),
 NEW.display_name,'operator',NEW.created_at,NEW.created_at);
 INSERT INTO admin_users(id,email,role,status,password_hash,display_name,created_at,accepted_at,updated_at)
 VALUES(NEW.admin_user_id,'info@ikanisa.com','owner','active',NEW.password_hash,NEW.display_name,NEW.created_seconds,NEW.created_seconds,NEW.created_seconds);
 INSERT INTO admin_principal_links(admin_user_id,user_id,approved_by,approved_at)
 VALUES(NEW.admin_user_id,NEW.principal_user_id,NEW.approval_reference,NEW.created_at);
 INSERT INTO admin_account_audit(id,actor_id,subject_id,action,occurred_at)
 VALUES(NEW.operation_id,NEW.admin_user_id,NEW.admin_user_id,'explicit_owner_bootstrapped',NEW.created_seconds);
END;
CREATE TRIGGER admin_owner_bootstrap_no_delete BEFORE DELETE ON admin_owner_bootstrap_claims
 BEGIN SELECT RAISE(ABORT,'retain_owner_bootstrap'); END;
CREATE TRIGGER admin_owner_bootstrap_no_update BEFORE UPDATE ON admin_owner_bootstrap_claims
 BEGIN SELECT RAISE(ABORT,'immutable_owner_bootstrap'); END;
CREATE TRIGGER admin_principal_link_immutable BEFORE UPDATE ON admin_principal_links
 BEGIN SELECT RAISE(ABORT,'explicit_principal_link_required'); END;
CREATE TRIGGER admin_principal_link_revoked BEFORE DELETE ON admin_principal_links BEGIN
 UPDATE auth_sessions SET revoked_at=unixepoch(),revocation_reason='admin_principal_unlinked' WHERE user_id=OLD.user_id AND surface='admin' AND revoked_at IS NULL;
 DELETE FROM admin_sessions WHERE user_id=OLD.admin_user_id;
 DELETE FROM admin_grants WHERE user_id=OLD.user_id AND granted_by='admin-account:'||OLD.admin_user_id;
 DELETE FROM admin_role_assignments WHERE user_id=OLD.user_id AND granted_by='admin-account:'||OLD.admin_user_id;
END;
CREATE TRIGGER admin_role_capabilities_no_delete BEFORE DELETE ON admin_account_role_capabilities
 BEGIN SELECT RAISE(ABORT,'approved_role_capabilities_immutable'); END;
CREATE TRIGGER admin_role_capabilities_no_update BEFORE UPDATE ON admin_account_role_capabilities
 BEGIN SELECT RAISE(ABORT,'approved_role_capabilities_immutable'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_log BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_log BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
CREATE TRIGGER auth_mfa_claim_no_delete BEFORE DELETE ON auth_mfa_claims
 BEGIN SELECT RAISE(ABORT,'retain_mfa_claim'); END;
CREATE TRIGGER auth_mfa_claim_no_update BEFORE UPDATE ON auth_mfa_claims
 BEGIN SELECT RAISE(ABORT,'immutable_mfa_claim'); END;
CREATE TRIGGER auth_mfa_counter_monotonic BEFORE UPDATE OF last_totp_counter ON auth_mfa_factors
 WHEN OLD.last_totp_counter IS NOT NULL AND (NEW.last_totp_counter IS NULL OR NEW.last_totp_counter<=OLD.last_totp_counter)
 BEGIN SELECT RAISE(ABORT,'mfa_code_replay'); END;
CREATE TRIGGER auth_mfa_factor_final BEFORE UPDATE ON auth_mfa_factors WHEN OLD.status='revoked'
 BEGIN SELECT RAISE(ABORT,'mfa_revocation_is_final'); END;
CREATE TRIGGER auth_mfa_factor_identity BEFORE UPDATE OF id,user_id,friendly_name,secret_ciphertext,created_at,enrollment_session_id ON auth_mfa_factors
 BEGIN SELECT RAISE(ABORT,'immutable_mfa_factor'); END;
CREATE TRIGGER auth_mfa_verified_session BEFORE UPDATE OF assurance_level,mfa_at,mfa_factor_id ON auth_sessions
 WHEN NEW.assurance_level=2 AND NOT EXISTS(SELECT 1 FROM auth_mfa_claims c JOIN auth_mfa_factors f ON f.id=c.factor_id
   WHERE c.session_id=NEW.id AND c.factor_id=NEW.mfa_factor_id AND c.user_id=NEW.user_id AND c.verified_at=NEW.mfa_at
     AND f.status='verified' AND f.last_totp_counter=c.totp_counter)
 BEGIN SELECT RAISE(ABORT,'verified_mfa_claim_required'); END;
CREATE TRIGGER auth_rate_admission BEFORE INSERT ON auth_rate_claims BEGIN
 SELECT (CASE WHEN
   COALESCE((SELECT used FROM auth_rate_buckets WHERE bucket_key=NEW.identity_bucket),0)>=NEW.identity_limit
   OR COALESCE((SELECT used FROM auth_rate_buckets WHERE bucket_key=NEW.ip_bucket),0)>=NEW.ip_limit
   OR COALESCE((SELECT used FROM auth_rate_buckets WHERE bucket_key=NEW.global_bucket),0)>=NEW.global_limit
   OR EXISTS(SELECT 1 FROM auth_otp_throttles WHERE identity_hash=NEW.identity_hash
      AND last_requested_at+NEW.cooldown_seconds>NEW.requested_at)
 THEN RAISE(ABORT,'auth_rate_limited') END);
 INSERT INTO auth_rate_buckets(bucket_key,used,window_ends_at)
 VALUES(NEW.identity_bucket,1,NEW.hourly_window_ends_at)
 ON CONFLICT(bucket_key) DO UPDATE SET used=used+1;
 INSERT INTO auth_rate_buckets(bucket_key,used,window_ends_at)
 VALUES(NEW.ip_bucket,1,NEW.hourly_window_ends_at)
 ON CONFLICT(bucket_key) DO UPDATE SET used=used+1;
 INSERT INTO auth_rate_buckets(bucket_key,used,window_ends_at)
 VALUES(NEW.global_bucket,1,NEW.daily_window_ends_at)
 ON CONFLICT(bucket_key) DO UPDATE SET used=used+1;
 INSERT INTO auth_otp_throttles(identity_hash,last_requested_at)
 VALUES(NEW.identity_hash,NEW.requested_at)
 ON CONFLICT(identity_hash) DO UPDATE SET last_requested_at=NEW.requested_at;
END;
CREATE TRIGGER auth_session_identity_no_update
 BEFORE UPDATE OF id,user_id,surface,auth_at,created_at,expires_at ON auth_sessions
 BEGIN SELECT RAISE(ABORT,'immutable_session_identity'); END;
CREATE TRIGGER auth_session_no_unrevoke BEFORE UPDATE OF revoked_at,revocation_reason ON auth_sessions
 WHEN OLD.revoked_at IS NOT NULL AND (NEW.revoked_at IS NOT OLD.revoked_at OR NEW.revocation_reason IS NOT OLD.revocation_reason)
 BEGIN SELECT RAISE(ABORT,'session_revocation_is_final'); END;
CREATE TRIGGER auth_verification_no_delete BEFORE DELETE ON auth_otp_verifications
 BEGIN SELECT RAISE(ABORT,'retain_auth_verification'); END;
CREATE TRIGGER auth_verification_no_update BEFORE UPDATE ON auth_otp_verifications
 BEGIN SELECT RAISE(ABORT,'immutable_auth_verification'); END;
CREATE TRIGGER evidence_no_delete BEFORE DELETE ON payment_evidence BEGIN SELECT RAISE(ABORT,'retain_financial_evidence'); END;
CREATE TRIGGER evidence_no_rewrite BEFORE UPDATE OF object_key,object_sha256,size_bytes,content_type,authenticity,external_reference,receiver_momo_number,amount_minor,currency,observed_at ON payment_evidence BEGIN SELECT RAISE(ABORT,'immutable_evidence'); END;
CREATE TRIGGER evidence_route_snapshot_immutable BEFORE UPDATE OF receiver_network,receiver_display_label ON payment_evidence BEGIN SELECT RAISE(ABORT,'immutable_evidence'); END;
CREATE TRIGGER ledger_no_delete BEFORE DELETE ON ledger_entries BEGIN SELECT RAISE(ABORT,'immutable_ledger'); END;
CREATE TRIGGER ledger_no_update BEFORE UPDATE ON ledger_entries BEGIN SELECT RAISE(ABORT,'immutable_ledger'); END;
CREATE TRIGGER membership_revision_monotonic AFTER UPDATE OF role,active ON memberships
 WHEN NEW.revision=OLD.revision BEGIN UPDATE memberships SET revision=revision+1 WHERE id=NEW.id; END;
CREATE TRIGGER mutation_authority BEFORE INSERT ON mutation_guards BEGIN
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM auth_sessions s JOIN users u ON u.id=s.user_id WHERE s.id=NEW.session_id AND s.user_id=NEW.user_id AND s.revoked_at IS NULL AND s.expires_at>NEW.now_seconds AND u.access_status='active') THEN RAISE(ABORT,'session_changed') END);
 SELECT (CASE WHEN NEW.fresh_seconds IS NOT NULL AND NOT EXISTS(SELECT 1 FROM auth_sessions s WHERE s.id=NEW.session_id AND (CASE WHEN s.assurance_level=2 THEN s.mfa_at ELSE s.auth_at END)>=NEW.now_seconds-NEW.fresh_seconds) THEN RAISE(ABORT,'fresh_auth_required') END);
 SELECT (CASE WHEN NEW.minimum_assurance IS NOT NULL AND NOT EXISTS(SELECT 1 FROM auth_sessions s JOIN auth_mfa_factors f ON f.id=s.mfa_factor_id AND f.status='verified' WHERE s.id=NEW.session_id AND s.assurance_level>=NEW.minimum_assurance AND s.mfa_at=NEW.expected_mfa_at AND s.mfa_at>=NEW.now_seconds-300 AND s.mfa_factor_id IS NOT NULL) THEN RAISE(ABORT,'mfa_required') END);
 SELECT (CASE WHEN NEW.permission IS NOT NULL AND NOT EXISTS(SELECT 1 FROM auth_sessions s JOIN admin_grants g ON g.user_id=s.user_id WHERE s.id=NEW.session_id AND s.surface='admin' AND g.permission=NEW.permission) THEN RAISE(ABORT,'permission_denied') END);
 SELECT (CASE WHEN NEW.collection_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM memberships m JOIN collections c ON c.id=m.collection_id WHERE m.collection_id=NEW.collection_id AND m.user_id=NEW.user_id AND m.active=1 AND c.status='active' AND (NEW.required_group_role IS NULL OR m.role=NEW.required_group_role OR (NEW.required_group_role='admin' AND m.role='owner'))) THEN RAISE(ABORT,'group_access_denied') END);
 SELECT (CASE WHEN NEW.invite_collection_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM collections c WHERE c.id=NEW.invite_collection_id AND c.status='active' AND c.share_code_hash=NEW.expected_share_hash AND c.share_code_version=NEW.expected_share_version) THEN RAISE(ABORT,'invitation_changed') END);
 SELECT (CASE WHEN NEW.recipient_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.user_id=NEW.recipient_user_id AND m.collection_id=NEW.recipient_collection_id AND m.active=1 AND u.access_status='active') THEN RAISE(ABORT,'recipient_changed') END);
 SELECT (CASE WHEN NEW.expected_preference_revision IS NOT NULL AND coalesce((SELECT revision FROM notification_preferences WHERE user_id=NEW.user_id),1)!=NEW.expected_preference_revision THEN RAISE(ABORT,'stale_preferences') END);
 SELECT (CASE WHEN NEW.expected_collection_revision IS NOT NULL AND NOT EXISTS(SELECT 1 FROM collections c WHERE c.id=NEW.collection_id AND c.revision=NEW.expected_collection_revision) THEN RAISE(ABORT,'stale_collection') END);
 SELECT (CASE WHEN NEW.expected_payment_revision IS NOT NULL AND NOT EXISTS(SELECT 1 FROM payments p WHERE p.id=NEW.payment_id AND p.revision=NEW.expected_payment_revision) THEN RAISE(ABORT,'stale_payment') END);
END;
CREATE TRIGGER mutation_target_collection BEFORE INSERT ON mutation_guards BEGIN
 SELECT (CASE WHEN NEW.target_collection_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM collections c WHERE c.id=NEW.target_collection_id AND c.status='active' AND (NEW.expected_target_collection_revision IS NULL OR c.revision=NEW.expected_target_collection_revision)) THEN RAISE(ABORT,'stale_collection') END);
END;
CREATE TRIGGER native_capabilities_immutable BEFORE UPDATE ON native_capabilities BEGIN SELECT RAISE(ABORT,'native_evidence_immutable'); END;
CREATE TRIGGER native_capabilities_no_delete BEFORE DELETE ON native_capabilities BEGIN SELECT RAISE(ABORT,'native_evidence_immutable'); END;
CREATE TRIGGER native_capability_authority BEFORE INSERT ON native_capabilities BEGIN
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM native_reservations r JOIN auth_sessions s ON s.id=r.session_id JOIN users u ON u.id=r.user_id WHERE r.id=NEW.reservation_id AND r.state='decode_started' AND r.expires_seconds>NEW.created_seconds AND r.user_id=NEW.user_id AND r.session_id=NEW.session_id AND r.action=NEW.action AND r.receiver_hash=NEW.receiver_hash AND r.payload_sha256=NEW.payload_sha256 AND r.verified_phone=NEW.verified_phone AND s.revoked_at IS NULL AND s.expires_at>NEW.created_seconds AND u.access_status='active' AND u.phone=NEW.verified_phone) THEN RAISE(ABORT,'native_completion_denied') END);
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM native_consents c WHERE c.id=(SELECT max(id) FROM native_consents WHERE user_id=NEW.user_id) AND c.session_id=NEW.session_id AND c.enabled=1 AND c.receiver_hash=NEW.receiver_hash AND c.created_seconds BETWEEN NEW.created_seconds-600 AND NEW.created_seconds) THEN RAISE(ABORT,'native_consent_required') END);
END;
CREATE TRIGGER native_claim_authority BEFORE INSERT ON native_capability_claims BEGIN
 SELECT (CASE WHEN NEW.claimed_seconds NOT BETWEEN unixepoch()-5 AND unixepoch()+5 THEN RAISE(ABORT,'native_claim_expired') END);
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM native_capabilities c JOIN native_completions d ON d.capability_id=c.id JOIN auth_sessions s ON s.id=c.session_id JOIN users u ON u.id=c.user_id WHERE c.id=NEW.capability_id AND c.user_id=NEW.user_id AND c.session_id=NEW.session_id AND c.action=NEW.action AND c.payload_sha256=NEW.payload_sha256 AND c.receiver_hash=NEW.receiver_hash AND c.expires_seconds>max(NEW.claimed_seconds,unixepoch()) AND s.revoked_at IS NULL AND s.expires_at>max(NEW.claimed_seconds,unixepoch()) AND u.access_status='active' AND u.phone=c.verified_phone) THEN RAISE(ABORT,'native_capability_denied') END);
 SELECT (CASE WHEN NOT EXISTS(SELECT 1 FROM native_consents c WHERE c.id=(SELECT max(id) FROM native_consents WHERE user_id=NEW.user_id) AND c.session_id=NEW.session_id AND c.enabled=1 AND c.receiver_hash=NEW.receiver_hash AND c.created_seconds BETWEEN NEW.claimed_seconds-600 AND NEW.claimed_seconds) THEN RAISE(ABORT,'native_consent_required') END);
END;
